1	import Index from "@/legacy-pages/Index";
2	export default function JobsPage() { return <Index />; }
3

1	"use client";
2	
3	import React, { useState, useCallback, useEffect, useMemo } from "react";
4	import { useSearchParams, usePathname, useRouter } from "next/navigation";
5	import { useQuery, useQueryClient } from "@tanstack/react-query";
6	import { useAuth } from "@/hooks/useAuth";
7	import { supabase } from "@/integrations/supabase/client";
8	import AuthDialog from "@/components/AuthDialog";
9	import JobDetailView from "@/components/JobDetailView";
10	import JobsOverviewCard from "@/components/JobsOverviewCard";
11	import { Card, CardContent } from "@/components/ui/card";
12	import { Badge } from "@/components/ui/badge";
13	import { Button } from "@/components/ui/button";
14	import { Plus, Briefcase, FileText, Coins, CheckCircle2, ChevronRight, ChevronLeft } from "lucide-react";
15	import { format } from "date-fns";
16	import { toast } from "sonner";
17	import OnboardingWizard from "@/components/OnboardingWizard";
18	
19	export interface PastJob {
20	  id: string;
21	  title: string | null;
22	  job_description: string;
23	  status: string;
24	  created_at: string;
25	  resume_count: number;
26	  jd_analysis_json: any;
27	  dynamic_weights_json: Record<string, number> | null;
28	  inbox_email: string | null;
29	}
30	
31	export interface Result {
32	  id: string;
33	  resume_id: string;
34	  overall_score: number;
35	  missing_skills: string[];
36	  summary: string | null;
37	  interview_questions: any;
38	  filename: string;
39	  file_path: string | null;
40	  candidate_name: string | null;
41	  candidate_email?: string | null;
42	  candidate_phone?: string | null;
43	  candidate_location?: string | null;
44	  // Dynamic scoring fields
45	  hard_fit?: boolean;
46	  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
47	  confidence?: number;
48	  strengths_json?: string[];
49	  gaps_json?: string[];
50	  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string; matched_preferred?: string[]; missing_preferred?: string[] };
51	  matched_must_haves?: string[];
52	  missing_must_haves?: string[];
53	  scoring_version?: string;
54	  pending?: boolean;
55	  parsed_json?: any;
56	  assigned_to?: string | null;
57	  source?: string | null;
58	}
59	
60	export interface ExistingResume {
61	  id: string;
62	  filename: string;
63	  file_path: string | null;
64	  candidate_name: string | null;
65	  created_at: string;
66	  source?: string | null;
67	}
68	
69	type ViewMode = "dashboard" | "my-jobs" | "job-detail" | "new-job";
70	
71	const ONBOARDING_KEY = "rankora_onboarding_done";
72	
73	const Index = () => {
74	  const { user, profile, loading } = useAuth();
75	  const searchParams = useSearchParams();
76	  const pathname = usePathname() ?? "/";
77	  const router = useRouter();
78	
79	  // Auth wall: server-side proxy already redirects unauthenticated users,
80	  // but this catches client-side navigation and stale-session edge cases.
81	  if (!loading && !user) {
82	    router.replace("/auth");
83	    return null;
84	  }
85	
86	  // Helper to clear all query params (replaces react-router setSearchParams({}, { replace: true }))
87	  const clearSearchParams = useCallback(() => {
88	    router.replace(pathname);
89	  }, [pathname, router]);
90	
91	  // Show onboarding wizard for first-time users
92	  const [showOnboarding, setShowOnboarding] = useState(() => {
93	    if (typeof window === "undefined") return false;
94	    return !localStorage.getItem(ONBOARDING_KEY);
95	  });
96	
97	  const completeOnboarding = useCallback(() => {
98	    localStorage.setItem(ONBOARDING_KEY, "1");
99	    setShowOnboarding(false);
100	  }, []);
101	
102	  const queryClient = useQueryClient();
103	
104	  const { data: pastJobs = [], isLoading: loadingPastJobs } = useQuery({
105	    queryKey: ["pastJobs", user?.id],
106	    queryFn: async () => {
107	      const { data: jobs } = await supabase
108	        .from("jobs")
109	        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
110	        .eq("user_id", user!.id)
111	        .order("created_at", { ascending: false })
112	        .limit(50);
113	      if (!jobs) return [];
114	      return jobs.map((j: any) => ({
115	        id: j.id,
116	        title: j.title,
117	        job_description: j.job_description,
118	        status: j.status,
119	        created_at: j.created_at,
120	        resume_count: j.resumes?.[0]?.count ?? 0,
121	        jd_analysis_json: j.jd_analysis_json,
122	        dynamic_weights_json: j.dynamic_weights_json,
123	        inbox_email: j.inbox_email ?? null,
124	      })) as PastJob[];
125	    },
126	    enabled: !!user,
127	    staleTime: 2 * 60 * 1000,
128	  });
129	
130	  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
131	  const [view, setView] = useState<ViewMode>(pathname === "/jobs" ? "my-jobs" : "dashboard");
132	  const [results, setResults] = useState<Result[]>([]);
133	  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
134	  const [authOpen, setAuthOpen] = useState(false);
135	
136	  const selectedJob = useMemo(() => pastJobs.find((j) => j.id === selectedJobId) ?? null, [pastJobs, selectedJobId]);
137	
138	  // Sync view with route path
139	  useEffect(() => {
140	    if (pathname === "/jobs") {
141	      setView("my-jobs");
142	      setSelectedJobId(null);
143	    }
144	  }, [pathname]);
145	
146	  // Handle URL params for deep linking
147	  useEffect(() => {
148	    const jobParam = searchParams?.get("job") ?? null;
149	    const newParam = searchParams?.get("new") ?? null;
150	
151	    if (jobParam && user) {
152	      loadJobData(jobParam);
153	      clearSearchParams();
154	    } else if (newParam && user) {
155	      handleNewJob();
156	      clearSearchParams();
157	    }
158	    // eslint-disable-next-line react-hooks/exhaustive-deps
159	  }, [searchParams, user]);
160	
161	  const loadJobData = async (jobId: string) => {
162	    setSelectedJobId(jobId);
163	    setView("job-detail");
164	    try {
165	      // Single query for all resume data (was 2 separate queries)
166	      const { data: allResumes } = await supabase
167	        .from("resumes")
168	        .select("id, filename, file_path, candidate_name, created_at, parsed_json, source")
169	        .eq("job_id", jobId)
170	        .order("created_at", { ascending: false });
171	
172	      const resumeData = allResumes ?? [];
173	      setExistingResumes(resumeData.map((r) => ({
174	        id: r.id, filename: r.filename, file_path: r.file_path,
175	        candidate_name: r.candidate_name, created_at: r.created_at,
176	        source: (r as { source?: string | null }).source ?? null,
177	      })));
178	
179	      if (resumeData.length === 0) {
180	        setResults([]);
181	        return;
182	      }
183	
184	      const resumeIds = resumeData.map((r) => r.id);
185	      const { data: resultData } = await supabase
186	        .from("results")
187	        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
188	        .in("resume_id", resumeIds);
189	
190	      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
191	      const allMerged: Result[] = (resultData ?? []).map((r: any) => {
192	        const resume = resumeMap.get(r.resume_id);
193	        const parsed = resume?.parsed_json as any;
194	        return {
195	          ...r,
196	          overall_score: r.overall_score ?? 0,
197	          missing_skills: r.missing_skills ?? [],
198	          filename: resume?.filename ?? "Unknown",
199	          file_path: resume?.file_path ?? null,
200	          candidate_name: resume?.candidate_name ?? null,
201	          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
202	          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
203	          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
204	          parsed_json: resume?.parsed_json ?? null,
205	          source: (resume as { source?: string | null })?.source ?? null,
206	        };
207	      });
208	      // Deduplicate by resume_id — keep highest scoring result per resume
209	      const deduped = new Map<string, Result>();
210	      for (const r of allMerged) {
211	        const existing = deduped.get(r.resume_id);
212	        if (!existing || r.overall_score > existing.overall_score) {
213	          deduped.set(r.resume_id, r);
214	        }
215	      }
216	      const merged = Array.from(deduped.values());
217	      merged.sort((a, b) => b.overall_score - a.overall_score);
218	      setResults(merged);
219	    } catch (err) {
220	      toast.error("Failed to load job data");
221	    }
222	  };
223	
224	  const handleNewJob = () => {
225	    setSelectedJobId(null);
226	    setView("new-job");
227	    setResults([]);
228	    setExistingResumes([]);
229	  };
230	
231	  const handleGoToDashboard = () => {
232	    setSelectedJobId(null);
233	    setView("dashboard");
234	    setResults([]);
235	    setExistingResumes([]);
236	    router.replace("/");
237	  };
238	
239	  const handleGoToMyJobs = () => {
240	    setSelectedJobId(null);
241	    setView("my-jobs");
242	    setResults([]);
243	    setExistingResumes([]);
244	    router.replace("/jobs");
245	  };
246	
247	  const handleJobCreated = (job: PastJob) => {
248	    queryClient.setQueryData<PastJob[]>(["pastJobs", user?.id], (prev) => [job, ...(prev ?? [])]);
249	    setSelectedJobId(job.id);
250	    loadJobData(job.id);
251	  };
252	
253	  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
254	    queryClient.setQueryData<PastJob[]>(["pastJobs", user?.id], (prev) =>
255	      (prev ?? []).map((j) => (j.id === jobId ? { ...j, ...updates } : j))
256	    );
257	  };
258	
259	  const handleDeleteJobs = async (jobIds: string[]) => {
260	    try {
261	      const { error } = await supabase.from("jobs").delete().in("id", jobIds);
262	      if (error) throw error;
263	      queryClient.setQueryData<PastJob[]>(["pastJobs", user?.id], (prev) =>
264	        (prev ?? []).filter((j) => !jobIds.includes(j.id))
265	      );
266	    } catch (err: any) {
267	      toast.error(err?.message || "Failed to delete jobs");
268	    }
269	  };
270	
271	  const requireAuth = useCallback(() => {
272	    if (!user) { setAuthOpen(true); return true; }
273	    return false;
274	  }, [user]);
275	
276	  return (
277	    <>
278	        <div className="flex-1 overflow-y-auto">
279	
280	        {/* Dashboard view */}
281	        {view === "dashboard" && user ? (
282	          <main className="w-full px-6 sm:px-8 lg:px-10 py-8 space-y-6">
283	            {/* Hero Section — Greeting + Create Button */}
284	            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
285	              <div>
286	                <h1 className="text-2xl font-bold text-foreground">
287	                  Welcome back, {user.user_metadata?.full_name?.split(" ")[0] || user.email?.split("@")[0]}!
288	                </h1>
289	                <p className="text-sm text-muted-foreground mt-1">
290	                  Here's an overview of your hiring activity and insights.
291	                </p>
292	              </div>
293	              <Button className="gap-2" onClick={handleNewJob}>
294	                <Plus className="h-4 w-4" /> Create Job
295	              </Button>
296	            </div>
297	
298	            {/* Stats Cards */}
299	            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
300	              {[
301	                { label: "Total Jobs", value: pastJobs.length, icon: Briefcase, color: "bg-blue-100 text-blue-600" },
302	                { label: "Total Resumes", value: pastJobs.reduce((s, j) => s + j.resume_count, 0), icon: FileText, color: "bg-emerald-100 text-emerald-600" },
303	                { label: "Credits Left", value: (() => { const p = profile; if (!p) return 0; const s = (p.subscription_credits ?? 0) + (p.topup_credits ?? 0) + (p.bonus_credits ?? 0); return s > 0 ? s : (p.credits ?? 0); })(), icon: Coins, color: "bg-amber-100 text-amber-600" },
304	                { label: "Jobs Completed", value: pastJobs.filter(j => j.status === "completed").length, icon: CheckCircle2, color: "bg-violet-100 text-violet-600" },
305	              ].map((s) => (
306	                <Card key={s.label} className="border border-border/60 shadow-sm hover:shadow-md transition-shadow">
307	                  <CardContent className="px-5 py-4 flex items-center gap-4">
308	                    <div className={`h-11 w-11 rounded-xl flex items-center justify-center shrink-0 ${s.color}`}>
309	                      <s.icon className="h-5 w-5" />
310	                    </div>
311	                    <div>
312	                      <p className="text-2xl font-bold tabular-nums text-foreground">{s.value}</p>
313	                      <p className="text-xs text-muted-foreground font-medium">{s.label}</p>
314	                    </div>
315	                  </CardContent>
316	                </Card>
317	              ))}
318	            </div>
319	
320	            {/* Recent Jobs */}
321	            {pastJobs.length > 0 && (
322	              <div className="space-y-3">
323	                <div className="flex items-center justify-between">
324	                  <h2 className="text-sm font-semibold text-foreground">Recent Jobs</h2>
325	                  <button onClick={handleGoToMyJobs} className="text-xs font-medium text-primary hover:text-primary/80 transition-colors">
326	                    View All Jobs →
327	                  </button>
328	                </div>
329	                <div className="grid gap-3">
330	                  {pastJobs.slice(0, 5).map((job) => (
331	                    <Card key={job.id} className="cursor-pointer hover:shadow-md transition-all border border-border/60" onClick={() => loadJobData(job.id)}>
332	                      <CardContent className="px-5 py-3.5 flex items-center justify-between">
333	                        <div className="flex items-center gap-3 min-w-0">
334	                          <div className="h-9 w-9 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
335	                            <Briefcase className="h-4 w-4 text-primary" />
336	                          </div>
337	                          <div className="min-w-0">
338	                            <p className="text-sm font-medium text-foreground truncate">{job.title || "Untitled Job"}</p>
339	                            <p className="text-xs text-muted-foreground mt-0.5">
340	                              {job.resume_count} resume{job.resume_count !== 1 ? "s" : ""} · {format(new Date(job.created_at), "MMM d, yyyy")}
341	                            </p>
342	                          </div>
343	                        </div>
344	                        <div className="flex items-center gap-3 shrink-0">
345	                          <Badge
346	                            variant={job.status === "completed" ? "success" : job.status === "pending" || job.status === "processing" ? "warning" : "outline"}
347	                            className="text-xs"
348	                          >
349	                            {job.status.charAt(0).toUpperCase() + job.status.slice(1)}
350	                          </Badge>
351	                          <ChevronRight className="h-4 w-4 text-muted-foreground" />
352	                        </div>
353	                      </CardContent>
354	                    </Card>
355	                  ))}
356	                </div>
357	              </div>
358	            )}
359	
360	            {/* Getting started guide — show only for new users */}
361	            {pastJobs.length === 0 && !loadingPastJobs && (
362	              <Card className="border border-border/60 shadow-sm">
363	                <CardContent className="px-5 py-4 space-y-3">
364	                  <h2 className="text-sm font-medium text-foreground">Getting Started</h2>
365	                  <div className="space-y-2.5">
366	                    {[
367	                      { step: "1", text: "Click \"Create New Job\" and paste a job description" },
368	                      { step: "2", text: "Upload candidate resumes (PDF, DOCX, or forward via email)" },
369	                      { step: "3", text: "AI ranks all candidates with scores, strengths, and gaps" },
370	                    ].map((item) => (
371	                      <div key={item.step} className="flex items-start gap-3 text-sm">
372	                        <span className="h-5 w-5 rounded-full bg-primary text-primary-foreground text-xs font-bold flex items-center justify-center shrink-0 mt-0.5">{item.step}</span>
373	                        <span className="text-muted-foreground">{item.text}</span>
374	                      </div>
375	                    ))}
376	                  </div>
377	                </CardContent>
378	              </Card>
379	            )}
380	          </main>
381	        ) : view === "my-jobs" && user ? (
382	          /* My Jobs view — full management */
383	          <main className="w-full px-6 sm:px-8 lg:px-10 py-8 space-y-6">
384	            <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4">
385	              <div className="space-y-1">
386	                <h1 className="text-2xl font-bold text-foreground">My Jobs</h1>
387	                <p className="text-sm text-muted-foreground">Manage all your job postings.</p>
388	              </div>
389	              <Button className="gap-2 shrink-0" onClick={handleNewJob}>
390	                <Plus className="h-4 w-4" /> Create Job
391	              </Button>
392	            </div>
393	            <JobsOverviewCard jobs={pastJobs} loading={loadingPastJobs} onSelectJob={loadJobData} onDeleteJobs={handleDeleteJobs} />
394	          </main>
395	        ) : (
396	          <JobDetailView
397	            selectedJobId={selectedJobId}
398	            selectedJob={selectedJob}
399	            results={results}
400	            setResults={setResults}
401	            existingResumes={existingResumes}
402	            setExistingResumes={setExistingResumes}
403	            onJobCreated={handleJobCreated}
404	            onAuthRequired={() => setAuthOpen(true)}
405	            isAuthenticated={!!user}
406	            pastJobs={pastJobs}
407	            onJobUpdated={handleJobUpdated}
408	            onBack={handleGoToMyJobs}
409	          />
410	        )}
411	        </div>
412	
413	      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
414	
415	      {user && showOnboarding && (
416	        <OnboardingWizard
417	          open={showOnboarding}
418	          onComplete={completeOnboarding}
419	          onCreateJob={() => { completeOnboarding(); handleNewJob(); }}
420	          onGoToTeam={() => { completeOnboarding(); router.push("/team"); }}
421	          userName={user.user_metadata?.full_name?.split(" ")[0] || user.email?.split("@")[0] || "there"}
422	        />
423	      )}
424	    </>
425	  );
426	};
427	
428	export default Index;
