1	"use client";
2	
3	import { useState } from "react";
4	import { useQuery } from "@tanstack/react-query";
5	import { supabase } from "@/integrations/supabase/client";
6	import { Button } from "@/components/ui/button";
7	import { Badge } from "@/components/ui/badge";
8	import { Skeleton } from "@/components/ui/skeleton";
9	import { toast } from "sonner";
10	import {
11	  CheckCircle2,
12	  Copy,
13	  ExternalLink,
14	  Facebook,
15	  Linkedin,
16	  QrCode,
17	  Share2,
18	  Twitter,
19	  XCircle,
20	  Rss,
21	} from "lucide-react";
22	
23	interface JobDistributionPanelProps {
24	  jobId: string;
25	  jobTitle: string;
26	  slug?: string | null;
27	  teamId?: string | null;
28	  careerPageActive?: boolean;
29	}
30	
31	// ─── Simple QR Code (SVG-based, no npm package) ──────────────────────────────
32	// Uses the free qr.io API or falls back to a Google Charts-compatible URL.
33	function QrCodeImage({ url }: { url: string }) {
34	  const qrSrc = `https://api.qrserver.com/v1/create-qr-code/?data=${encodeURIComponent(url)}&size=160x160&format=png&margin=4`;
35	  return (
36	    <img
37	      src={qrSrc}
38	      alt="QR Code"
39	      width={160}
40	      height={160}
41	      className="rounded-lg border border-border"
42	      loading="lazy"
43	    />
44	  );
45	}
46	
47	const JobDistributionPanel = ({
48	  jobId,
49	  jobTitle,
50	  slug,
51	  teamId,
52	  careerPageActive = false,
53	}: JobDistributionPanelProps) => {
54	  const [showQr, setShowQr] = useState(false);
55	
56	  // Build URLs
57	  const APP_URL = process.env.NEXT_PUBLIC_APP_URL || window.location.origin;
58	  const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL as string;
59	
60	  const jobUrl = slug ? `${APP_URL}/careers/${slug}/jobs/${jobId}` : null;
61	  const indeedFeedUrl = teamId
62	    ? `${SUPABASE_URL}/functions/v1/indeed-feed?team_id=${teamId}`
63	    : null;
64	
65	  // Check whether career page has JSON-LD (i.e., career page is configured)
66	  const hasCareerPage = careerPageActive && !!slug;
67	
68	  // Share text
69	  const shareText = `We're hiring! ${jobTitle}${jobUrl ? ` → ${jobUrl}` : ""}`;
70	
71	  const handleCopy = (text: string, label: string) => {
72	    navigator.clipboard.writeText(text).then(() => {
73	      toast.success(`${label} copied`);
74	    });
75	  };
76	
77	  const openShare = (platform: "linkedin" | "twitter" | "facebook") => {
78	    if (!jobUrl) {
79	      toast.error("Enable your career page first to get a shareable job URL");
80	      return;
81	    }
82	    const encodedUrl = encodeURIComponent(jobUrl);
83	    const encodedText = encodeURIComponent(shareText);
84	
85	    const urls: Record<string, string> = {
86	      linkedin: `https://www.linkedin.com/sharing/share-offsite/?url=${encodedUrl}`,
87	      twitter: `https://twitter.com/intent/tweet?text=${encodedText}`,
88	      facebook: `https://www.facebook.com/sharer/sharer.php?u=${encodedUrl}`,
89	    };
90	
91	    window.open(urls[platform], "_blank", "noopener,noreferrer,width=600,height=500");
92	  };
93	
94	  return (
95	    <div className="space-y-4">
96	      {/* Google Jobs */}
97	      <DistributionRow
98	        icon={
99	          <div className="h-7 w-7 rounded bg-blue-50 dark:bg-blue-950/40 flex items-center justify-center shrink-0">
100	            <span className="text-xs font-bold text-blue-600">G</span>
101	          </div>
102	        }
103	        title="Google Jobs"
104	        description="Structured data (JSON-LD) enables Google to index your job postings"
105	        status={hasCareerPage ? "active" : "inactive"}
106	        statusLabel={hasCareerPage ? "Active" : "No career page"}
107	        actions={
108	          hasCareerPage ? (
109	            <Button
110	              variant="outline"
111	              size="sm"
112	              className="h-7 gap-1 text-xs"
113	              onClick={() =>
114	                window.open(
115	                  `https://search.google.com/test/rich-results?url=${encodeURIComponent(jobUrl!)}`,
116	                  "_blank",
117	                  "noopener,noreferrer"
118	                )
119	              }
