116	function slugify(name: string): string {
117	  const raw = name
118	    .toLowerCase()
119	    .replace(/[^a-z0-9]+/g, "-")
120	    .replace(/^-|-$/g, "")
121	    .slice(0, 60);
122	  // DB constraint requires minimum 3 chars starting and ending with alphanumeric.
123	  if (raw.length < 3) return raw.padEnd(3, "1");
124	  return raw;
125	}
